[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>CreativeHub — Online Classes for Creatives</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&family=Inter:wght@400;500;600&display=swap" rel="stylesheet" />
  <style>
    /* ── Reset & Tokens ── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --black: #000000;
      --green: #55DA9B;
      --purple: #5620C1;
      --white: #FFFFFF;
      --off-white: #F7F6F3;
      --gray-50: #F9FAFB;
      --gray-100: #F3F4F6;
      --gray-200: #E5E7EB;
      --gray-300: #D1D5DB;
      --gray-400: #9CA3AF;
      --gray-500: #6B7280;
      --gray-700: #374151;
      --gray-900: #111827;
      --hero-bg: #0C0C0E;
      --radius-sm: 8px;
      --radius-md: 14px;
      --radius-lg: 20px;
      --radius-xl: 28px;
      --radius-pill: 999px;
      --shadow-card: 0 2px 12px rgba(0,0,0,0.08), 0 1px 3px rgba(0,0,0,0.06);
      --shadow-card-hover: 0 8px 30px rgba(0,0,0,0.14);
      --transition: 200ms cubic-bezier(0.4,0,0.2,1);
      --font-head: 'Plus Jakarta Sans', sans-serif;
      --font-body: 'Inter', sans-serif;
    }
    html { scroll-behavior: smooth; }
    body {
      font-family: var(--font-body);
      color: var(--gray-900);
      background: var(--white);
      -webkit-font-smoothing: antialiased;
      overflow-x: hidden;
    }
    a { text-decoration: none; color: inherit; }
    img { display: block; max-width: 100%; }
    button { font-family: inherit; cursor: pointer; border: none; }

    /* ── Utilities ── */
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }

    /* ── Skip Link ── */
    .skip-link {
      position: absolute; top: -100px; left: 16px; z-index: 9999;
      background: var(--green); color: var(--black); padding: 8px 16px;
      border-radius: var(--radius-sm); font-weight: 600;
      transition: top var(--transition);
    }
    .skip-link:focus { top: 16px; }

    /* ──────────────────────────────────────────
       NAVBAR
    ────────────────────────────────────────── */
    .navbar {
      position: sticky; top: 0; z-index: 100;
      background: rgba(255,255,255,0.95);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--gray-200);
      height: 64px;
      display: flex; align-items: center;
    }
    .navbar .container {
      display: flex; align-items: center; justify-content: space-between; width: 100%;
    }
    .navbar-logo {
      display: flex; align-items: center; gap: 8px;
      font-family: var(--font-head); font-weight: 800; font-size: 20px; color: var(--black);
    }
    .navbar-logo-mark {
      width: 32px; height: 32px; background: var(--black); border-radius: 8px;
      display: flex; align-items: center; justify-content: center;
    }
    .navbar-logo-mark svg { width: 18px; height: 18px; }
    .navbar-links {
      display: flex; align-items: center; gap: 28px;
      list-style: none;
    }
    .navbar-links a {
      font-size: 14px; font-weight: 500; color: var(--gray-700);
      transition: color var(--transition);
    }
    .navbar-links a:hover { color: var(--black); }
    .navbar-actions { display: flex; align-items: center; gap: 10px; }
    .btn-ghost {
      background: transparent; padding: 8px 16px; border-radius: var(--radius-pill);
      font-size: 14px; font-weight: 600; color: var(--gray-700);
      transition: background var(--transition), color var(--transition);
    }
    .btn-ghost:hover { background: var(--gray-100); color: var(--black); }
    .btn-primary {
      background: var(--black); color: var(--white);
      padding: 9px 20px; border-radius: var(--radius-pill);
      font-size: 14px; font-weight: 700;
      transition: background var(--transition), transform var(--transition);
    }
    .btn-primary:hover { background: var(--gray-900); transform: translateY(-1px); }
    .btn-primary:active { transform: translateY(0); }

    /* ──────────────────────────────────────────
       HERO
    ────────────────────────────────────────── */
    .hero {
      background: var(--hero-bg);
      padding: 80px 0 60px;
      position: relative; overflow: hidden;
    }
    .hero-glow-1 {
      position: absolute; top: -120px; right: -120px;
      width: 500px; height: 500px; border-radius: 50%;
      background: radial-gradient(circle, rgba(86,32,193,0.35) 0%, transparent 70%);
      pointer-events: none;
    }
    .hero-glow-2 {
      position: absolute; bottom: -80px; left: -80px;
      width: 400px; height: 400px; border-radius: 50%;
      background: radial-gradient(circle, rgba(85,218,155,0.2) 0%, transparent 70%);
      pointer-events: none;
    }
    .hero-inner {
      position: relative; z-index: 1;
      display: flex; flex-direction: column; align-items: center; text-align: center;
    }
    .hero-badge {
      display: inline-flex; align-items: center; gap: 6px;
      background: rgba(85,218,155,0.15); border: 1px solid rgba(85,218,155,0.3);
      color: var(--green); border-radius: var(--radius-pill);
      padding: 5px 14px; font-size: 13px; font-weight: 600;
      margin-bottom: 24px;
    }
    .hero-badge-dot { width: 6px; height: 6px; background: var(--green); border-radius: 50%; }
    .hero-title {
      font-family: var(--font-head);
      font-size: clamp(36px, 6vw, 68px);
      font-weight: 900;
      line-height: 1.08;
      color: var(--white);
      max-width: 820px;
      letter-spacing: -0.03em;
    }
    .hero-title .accent-green { color: var(--green); }
    .hero-title .accent-purple { color: #A78BFA; }
    .hero-subtitle {
      font-size: 20px; font-weight: 600; color: rgba(255,255,255,0.7);
      margin-top: 16px;
    }
    .hero-cta-group {
      display: flex; flex-direction: column; align-items: center; gap: 12px;
      margin-top: 36px; width: 100%; max-width: 380px;
    }
    .btn-google {
      display: flex; align-items: center; justify-content: center; gap: 10px;
      width: 100%; padding: 14px 24px; border-radius: var(--radius-pill);
      background: var(--white); color: var(--gray-900);
      font-size: 15px; font-weight: 700;
      transition: transform var(--transition), box-shadow var(--transition);
      box-shadow: 0 2px 8px rgba(0,0,0,0.2);
    }
    .btn-google:hover { transform: translateY(-2px); box-shadow: 0 6px 20px rgba(0,0,0,0.25); }
    .btn-google:active { transform: translateY(0); }
    .btn-email {
      display: flex; align-items: center; justify-content: center; gap: 10px;
      width: 100%; padding: 14px 24px; border-radius: var(--radius-pill);
      background: var(--green); color: var(--black);
      font-size: 15px; font-weight: 700;
      transition: transform var(--transition), filter var(--transition);
    }
    .btn-email:hover { transform: translateY(-2px); filter: brightness(1.06); }
    .btn-email:active { transform: translateY(0); }
    .hero-legal {
      font-size: 11px; color: rgba(255,255,255,0.4); max-width: 420px;
      line-height: 1.6; margin-top: 14px;
    }
    .hero-legal a { color: rgba(255,255,255,0.55); text-decoration: underline; }

    /* Category Pills */
    .hero-categories { margin-top: 52px; width: 100%; }
    .hero-categories-label {
      font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.1em;
      color: rgba(255,255,255,0.4); margin-bottom: 14px;
    }
    .categories-scroll {
      display: flex; gap: 8px; overflow-x: auto; padding-bottom: 4px;
      scrollbar-width: none; justify-content: center; flex-wrap: wrap;
    }
    .categories-scroll::-webkit-scrollbar { display: none; }
    .category-pill {
      flex-shrink: 0; padding: 8px 18px; border-radius: var(--radius-pill);
      background: rgba(255,255,255,0.08); border: 1px solid rgba(255,255,255,0.12);
      color: rgba(255,255,255,0.75); font-size: 13px; font-weight: 500;
      cursor: pointer; transition: background var(--transition), color var(--transition), border-color var(--transition);
    }
    .category-pill:hover {
      background: rgba(85,218,155,0.15); border-color: rgba(85,218,155,0.4);
      color: var(--green);
    }

    /* ──────────────────────────────────────────
       FEATURES
    ────────────────────────────────────────── */
    .features { padding: 96px 0; background: var(--white); }
    .section-eyebrow {
      font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.1em;
      color: var(--purple); margin-bottom: 12px;
    }
    .section-title {
      font-family: var(--font-head); font-size: clamp(28px, 4vw, 44px);
      font-weight: 800; line-height: 1.15; letter-spacing: -0.02em; color: var(--black);
    }
    .features-grid {
      display: grid; grid-template-columns: 1fr 1fr;
      gap: 24px; margin-top: 56px;
    }
    .feature-card {
      background: var(--gray-50); border-radius: var(--radius-lg);
      padding: 32px; border: 1px solid var(--gray-200);
      transition: box-shadow var(--transition), transform var(--transition);
    }
    .feature-card:hover { box-shadow: var(--shadow-card-hover); transform: translateY(-3px); }
    .feature-icon {
      width: 48px; height: 48px; border-radius: var(--radius-md);
      display: flex; align-items: center; justify-content: center;
      margin-bottom: 20px;
    }
    .feature-icon.green { background: rgba(85,218,155,0.15); }
    .feature-icon.purple { background: rgba(86,32,193,0.1); }
    .feature-icon.black { background: var(--black); }
    .feature-icon.yellow { background: rgba(251,191,36,0.15); }
    .feature-icon svg { width: 24px; height: 24px; }
    .feature-title {
      font-family: var(--font-head); font-size: 18px; font-weight: 700;
      color: var(--black); margin-bottom: 8px;
    }
    .feature-desc { font-size: 15px; color: var(--gray-500); line-height: 1.65; }
    .feature-card.featured {
      background: var(--black); border-color: transparent; grid-column: span 2;
      display: flex; align-items: center; gap: 40px;
    }
    .feature-card.featured .feature-title { color: var(--white); }
    .feature-card.featured .feature-desc { color: rgba(255,255,255,0.6); }

    /* ──────────────────────────────────────────
       STATS
    ────────────────────────────────────────── */
    .stats {
      background: var(--black); padding: 72px 0;
    }
    .stats-grid {
      display: grid; grid-template-columns: repeat(4, 1fr); gap: 0;
    }
    .stat-item {
      text-align: center; padding: 24px 16px;
      border-right: 1px solid rgba(255,255,255,0.1);
    }
    .stat-item:last-child { border-right: none; }
    .stat-value {
      font-family: var(--font-head); font-size: clamp(36px, 5vw, 56px);
      font-weight: 900; color: var(--green); line-height: 1;
      letter-spacing: -0.03em;
    }
    .stat-label {
      font-size: 14px; font-weight: 500; color: rgba(255,255,255,0.55); margin-top: 8px;
    }

    /* ──────────────────────────────────────────
       COURSES
    ────────────────────────────────────────── */
    .courses { padding: 96px 0; background: var(--off-white); }
    .courses-header {
      display: flex; flex-direction: column; align-items: center; text-align: center;
      margin-bottom: 40px;
    }
    .courses-tabs {
      display: flex; gap: 6px; overflow-x: auto; padding-bottom: 2px;
      scrollbar-width: none; flex-wrap: wrap; justify-content: center;
      margin-bottom: 40px;
    }
    .courses-tabs::-webkit-scrollbar { display: none; }
    .tab-btn {
      flex-shrink: 0; padding: 8px 18px; border-radius: var(--radius-pill);
      background: transparent; border: 1.5px solid var(--gray-300);
      font-size: 13px; font-weight: 600; color: var(--gray-500);
      cursor: pointer; transition: all var(--transition);
    }
    .tab-btn:hover { border-color: var(--black); color: var(--black); }
    .tab-btn.active {
      background: var(--black); border-color: var(--black); color: var(--white);
    }
    .courses-grid {
      display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px;
    }
    .course-card {
      background: var(--white); border-radius: var(--radius-lg);
      overflow: hidden; border: 1px solid var(--gray-200);
      transition: box-shadow var(--transition), transform var(--transition);
      cursor: pointer;
    }
    .course-card:hover { box-shadow: var(--shadow-card-hover); transform: translateY(-4px); }
    .course-thumb {
      width: 100%; aspect-ratio: 16/10; overflow: hidden; position: relative;
      background: var(--gray-100);
    }
    .course-thumb-img {
      width: 100%; height: 100%; object-fit: cover;
      transition: transform 400ms ease;
    }
    .course-card:hover .course-thumb-img { transform: scale(1.05); }
    .course-thumb-placeholder {
      width: 100%; height: 100%;
      display: flex; align-items: center; justify-content: center;
    }
    .course-badge {
      position: absolute; top: 10px; left: 10px;
      background: var(--green); color: var(--black);
      font-size: 10px; font-weight: 800; text-transform: uppercase; letter-spacing: 0.05em;
      padding: 3px 8px; border-radius: var(--radius-pill);
    }
    .course-body { padding: 16px; }
    .course-title {
      font-family: var(--font-head); font-size: 14px; font-weight: 700;
      color: var(--black); line-height: 1.4;
      display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
    }
    .course-instructor { font-size: 12px; color: var(--gray-500); margin-top: 6px; font-weight: 500; }
    .course-meta {
      display: flex; align-items: center; justify-content: space-between;
      margin-top: 10px; padding-top: 10px; border-top: 1px solid var(--gray-100);
    }
    .course-students {
      display: flex; align-items: center; gap: 4px;
      font-size: 12px; color: var(--gray-500); font-weight: 500;
    }
    .course-students svg { width: 12px; height: 12px; }
    .course-duration {
      font-size: 12px; color: var(--gray-500); font-weight: 500;
    }

    /* ──────────────────────────────────────────
       CREATIVE FEED
    ────────────────────────────────────────── */
    .creative-feed { padding: 96px 0; background: var(--white); }
    .feed-layout {
      display: grid; grid-template-columns: 1fr 1fr; gap: 64px;
      align-items: center; margin-top: 56px;
    }
    .feed-features { display: flex; flex-direction: column; gap: 32px; }
    .feed-item { display: flex; gap: 20px; align-items: flex-start; }
    .feed-item-icon {
      width: 44px; height: 44px; border-radius: var(--radius-md);
      background: var(--black); display: flex; align-items: center; justify-content: center;
      flex-shrink: 0;
    }
    .feed-item-icon svg { width: 20px; height: 20px; }
    .feed-item-icon.green-bg { background: var(--green); }
    .feed-item-icon.purple-bg { background: var(--purple); }
    .feed-item-title {
      font-family: var(--font-head); font-size: 18px; font-weight: 700; color: var(--black);
      margin-bottom: 6px;
    }
    .feed-item-desc { font-size: 15px; color: var(--gray-500); line-height: 1.65; }
    .feed-visual {
      border-radius: var(--radius-xl); overflow: hidden;
      background: linear-gradient(135deg, #5620C1 0%, #1a0a4a 100%);
      padding: 32px; min-height: 380px; display: flex; flex-direction: column;
      justify-content: flex-end; position: relative;
    }
    .feed-visual-grid {
      display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 20px;
    }
    .feed-post {
      border-radius: var(--radius-md); overflow: hidden;
      aspect-ratio: 1; background: rgba(255,255,255,0.1);
      backdrop-filter: blur(6px); border: 1px solid rgba(255,255,255,0.15);
      display: flex; align-items: center; justify-content: center;
    }
    .feed-post-inner {
      width: 80%; height: 80%; border-radius: 8px;
    }
    .feed-post-1 { background: linear-gradient(135deg, #55DA9B 0%, #0D9488 100%); }
    .feed-post-2 { background: linear-gradient(135deg, #F97316 0%, #EA580C 100%); }
    .feed-post-3 { background: linear-gradient(135deg, #A78BFA 0%, #5620C1 100%); }
    .feed-post-4 { background: linear-gradient(135deg, #FBD38D 0%, #F59E0B 100%); }
    .feed-visual-caption {
      color: var(--white); font-family: var(--font-head);
      font-size: 20px; font-weight: 700; line-height: 1.3;
    }
    .feed-visual-sub { color: rgba(255,255,255,0.6); font-size: 13px; margin-top: 4px; }

    /* ──────────────────────────────────────────
       TEACHERS
    ────────────────────────────────────────── */
    .teachers { padding: 96px 0; background: var(--off-white); }
    .teachers-header { margin-bottom: 16px; }
    .teachers-subtitle {
      font-size: 16px; color: var(--gray-500); max-width: 560px;
      line-height: 1.65; margin-top: 12px;
    }
    .teachers-carousel-wrapper {
      position: relative; margin-top: 40px;
    }
    .teachers-carousel {
      display: flex; gap: 20px; overflow-x: auto;
      scroll-snap-type: x mandatory; scrollbar-width: none;
      padding-bottom: 4px;
    }
    .teachers-carousel::-webkit-scrollbar { display: none; }
    .teacher-card {
      flex-shrink: 0; width: 220px; border-radius: var(--radius-lg);
      background: var(--white); border: 1px solid var(--gray-200);
      padding: 24px; text-align: center; scroll-snap-align: start;
      transition: box-shadow var(--transition), transform var(--transition);
      cursor: pointer;
    }
    .teacher-card:hover { box-shadow: var(--shadow-card-hover); transform: translateY(-4px); }
    .teacher-avatar {
      width: 80px; height: 80px; border-radius: 50%; margin: 0 auto 14px;
      overflow: hidden; border: 3px solid var(--gray-200);
      display: flex; align-items: center; justify-content: center;
      font-family: var(--font-head); font-size: 28px; font-weight: 800;
      color: var(--white);
    }
    .teacher-name {
      font-family: var(--font-head); font-size: 15px; font-weight: 700; color: var(--black);
    }
    .teacher-specialty {
      font-size: 13px; color: var(--gray-500); margin-top: 4px; font-weight: 500;
    }
    .teacher-tag {
      display: inline-block; margin-top: 12px; padding: 4px 12px;
      border-radius: var(--radius-pill); background: var(--gray-100);
      font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em;
      color: var(--gray-700);
    }
    .carousel-nav {
      display: flex; gap: 8px; margin-top: 24px;
    }
    .carousel-btn {
      width: 40px; height: 40px; border-radius: 50%;
      background: var(--white); border: 1.5px solid var(--gray-300);
      display: flex; align-items: center; justify-content: center;
      cursor: pointer; transition: all var(--transition);
    }
    .carousel-btn:hover { background: var(--black); border-color: var(--black); }
    .carousel-btn:hover svg { stroke: var(--white); }
    .carousel-btn svg { width: 18px; height: 18px; stroke: var(--gray-700); transition: stroke var(--transition); }

    /* ──────────────────────────────────────────
       TESTIMONIALS
    ────────────────────────────────────────── */
    .testimonials { padding: 96px 0; background: var(--white); }
    .testimonials-header { text-align: center; margin-bottom: 56px; }
    .testimonials-grid {
      display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px;
    }
    .testimonial-card {
      background: var(--gray-50); border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg); padding: 28px;
      transition: box-shadow var(--transition), transform var(--transition);
    }
    .testimonial-card:hover { box-shadow: var(--shadow-card-hover); transform: translateY(-2px); }
    .testimonial-card:nth-child(1) { border-top: 3px solid var(--green); }
    .testimonial-card:nth-child(2) { border-top: 3px solid var(--purple); }
    .testimonial-card:nth-child(3) { border-top: 3px solid #F97316; }
    .testimonial-card:nth-child(4) { border-top: 3px solid #F59E0B; }
    .testimonial-stars {
      display: flex; gap: 2px; margin-bottom: 14px;
    }
    .testimonial-stars svg { width: 16px; height: 16px; fill: #F59E0B; stroke: none; }
    .testimonial-quote {
      font-size: 16px; color: var(--gray-700); line-height: 1.7;
      font-style: italic;
    }
    .testimonial-author {
      display: flex; align-items: center; gap: 12px; margin-top: 20px;
    }
    .testimonial-avatar {
      width: 40px; height: 40px; border-radius: 50%;
      display: flex; align-items: center; justify-content: center;
      font-family: var(--font-head); font-size: 16px; font-weight: 800; color: var(--white);
      flex-shrink: 0;
    }
    .testimonial-name {
      font-family: var(--font-head); font-size: 14px; font-weight: 700; color: var(--black);
    }
    .testimonial-role { font-size: 12px; color: var(--gray-500); }

    /* ──────────────────────────────────────────
       TEAMS
    ────────────────────────────────────────── */
    .teams { padding: 96px 0; background: var(--black); }
    .teams-inner {
      display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center;
    }
    .teams-content .section-eyebrow { color: var(--green); }
    .teams-content .section-title { color: var(--white); }
    .teams-desc {
      font-size: 17px; color: rgba(255,255,255,0.6); line-height: 1.75; margin-top: 20px;
    }
    .teams-cta {
      display: inline-flex; align-items: center; gap: 8px;
      margin-top: 32px; padding: 14px 28px; border-radius: var(--radius-pill);
      background: var(--green); color: var(--black); font-weight: 700; font-size: 15px;
      transition: filter var(--transition), transform var(--transition);
    }
    .teams-cta:hover { filter: brightness(1.08); transform: translateY(-2px); }
    .teams-visual {
      border-radius: var(--radius-xl);
      background: linear-gradient(135deg, rgba(85,218,155,0.1), rgba(86,32,193,0.2));
      border: 1px solid rgba(255,255,255,0.08); padding: 40px;
      min-height: 340px; display: flex; align-items: center; justify-content: center;
    }
    .teams-stats-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; width: 100%; }
    .teams-stat {
      background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.08);
      border-radius: var(--radius-lg); padding: 24px; text-align: center;
    }
    .teams-stat-val {
      font-family: var(--font-head); font-size: 32px; font-weight: 900; color: var(--green);
    }
    .teams-stat-lbl { font-size: 13px; color: rgba(255,255,255,0.5); margin-top: 4px; }

    /* ──────────────────────────────────────────
       FAQ
    ────────────────────────────────────────── */
    .faq { padding: 96px 0; background: var(--off-white); }
    .faq-header { text-align: center; margin-bottom: 56px; }
    .faq-list { max-width: 760px; margin: 0 auto; display: flex; flex-direction: column; gap: 12px; }
    .faq-item {
      background: var(--white); border: 1.5px solid var(--gray-200);
      border-radius: var(--radius-lg); overflow: hidden;
      transition: border-color var(--transition);
    }
    .faq-item.open { border-color: var(--black); }
    .faq-question {
      width: 100%; display: flex; justify-content: space-between; align-items: center;
      padding: 20px 24px; text-align: left; background: transparent;
      font-family: var(--font-head); font-size: 16px; font-weight: 700; color: var(--black);
      cursor: pointer; gap: 16px;
      transition: background var(--transition);
    }
    .faq-question:hover { background: var(--gray-50); }
    .faq-icon {
      flex-shrink: 0; width: 28px; height: 28px; border-radius: 50%;
      background: var(--gray-100); display: flex; align-items: center; justify-content: center;
      transition: background var(--transition), transform var(--transition);
    }
    .faq-item.open .faq-icon { background: var(--black); transform: rotate(45deg); }
    .faq-icon svg { width: 14px; height: 14px; stroke: var(--gray-700); transition: stroke var(--transition); }
    .faq-item.open .faq-icon svg { stroke: var(--white); }
    .faq-answer {
      max-height: 0; overflow: hidden;
      transition: max-height 300ms cubic-bezier(0.4,0,0.2,1), padding 300ms;
      padding: 0 24px;
    }
    .faq-answer-inner {
      padding-bottom: 20px;
      font-size: 15px; color: var(--gray-500); line-height: 1.75;
      border-top: 1px solid var(--gray-100); padding-top: 16px;
    }
    .faq-item.open .faq-answer { max-height: 400px; }

    /* ──────────────────────────────────────────
       FOOTER
    ────────────────────────────────────────── */
    .footer-cta {
      background: linear-gradient(135deg, var(--purple) 0%, #1a0a4a 100%);
      padding: 80px 0; text-align: center;
    }
    .footer-cta-title {
      font-family: var(--font-head); font-size: clamp(28px, 4vw, 44px);
      font-weight: 900; color: var(--white); letter-spacing: -0.02em; margin-bottom: 16px;
    }
    .footer-cta-sub { font-size: 17px; color: rgba(255,255,255,0.65); margin-bottom: 32px; }
    .footer-cta-btn {
      display: inline-flex; align-items: center; gap: 8px;
      padding: 16px 36px; border-radius: var(--radius-pill);
      background: var(--green); color: var(--black); font-family: var(--font-head);
      font-size: 16px; font-weight: 800;
      transition: filter var(--transition), transform var(--transition);
    }
    .footer-cta-btn:hover { filter: brightness(1.08); transform: translateY(-2px); }
    .footer-main {
      background: var(--gray-900); padding: 64px 0 40px;
    }
    .footer-grid {
      display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr; gap: 40px;
      padding-bottom: 48px; border-bottom: 1px solid rgba(255,255,255,0.08);
    }
    .footer-brand .navbar-logo { color: var(--white); margin-bottom: 16px; }
    .footer-brand-desc {
      font-size: 14px; color: rgba(255,255,255,0.45); line-height: 1.7; max-width: 240px;
    }
    .footer-col-title {
      font-family: var(--font-head); font-size: 13px; font-weight: 700;
      text-transform: uppercase; letter-spacing: 0.08em; color: rgba(255,255,255,0.5);
      margin-bottom: 16px;
    }
    .footer-col-links { list-style: none; display: flex; flex-direction: column; gap: 10px; }
    .footer-col-links a {
      font-size: 14px; color: rgba(255,255,255,0.65);
      transition: color var(--transition);
    }
    .footer-col-links a:hover { color: var(--white); }
    .footer-bottom {
      padding-top: 32px;
      display: flex; align-items: center; justify-content: space-between;
    }
    .footer-legal { font-size: 12px; color: rgba(255,255,255,0.3); max-width: 600px; line-height: 1.6; }
    .footer-copyright { font-size: 13px; color: rgba(255,255,255,0.35); flex-shrink: 0; }

    /* ──────────────────────────────────────────
       RESPONSIVE
    ────────────────────────────────────────── */
    @media (max-width: 1024px) {
      .courses-grid { grid-template-columns: repeat(3, 1fr); }
      .footer-grid { grid-template-columns: 1fr 1fr 1fr; }
      .footer-brand { grid-column: span 3; }
    }
    @media (max-width: 768px) {
      .navbar-links { display: none; }
      .features-grid { grid-template-columns: 1fr; }
      .feature-card.featured { flex-direction: column; gap: 0; }
      .stats-grid { grid-template-columns: repeat(2, 1fr); }
      .stat-item { border-right: none; border-bottom: 1px solid rgba(255,255,255,0.1); }
      .stat-item:nth-child(odd) { border-right: 1px solid rgba(255,255,255,0.1); }
      .stat-item:nth-last-child(-n+2) { border-bottom: none; }
      .courses-grid { grid-template-columns: repeat(2, 1fr); }
      .feed-layout { grid-template-columns: 1fr; }
      .feed-visual { min-height: 280px; }
      .testimonials-grid { grid-template-columns: 1fr; }
      .teams-inner { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: 1fr 1fr; }
      .footer-brand { grid-column: span 2; }
      .footer-bottom { flex-direction: column; gap: 12px; text-align: center; }
    }
    @media (max-width: 480px) {
      .hero { padding: 60px 0 40px; }
      .courses-grid { grid-template-columns: 1fr; }
      .stats-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-grid { grid-template-columns: 1fr; }
      .footer-brand { grid-column: span 1; }
      .btn-ghost { display: none; }
    }
    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; }
    }

    /* ── Scrollbar (courses tabs on mobile) ── */
    .tab-btn:focus-visible, .carousel-btn:focus-visible,
    .faq-question:focus-visible, .btn-google:focus-visible,
    .btn-email:focus-visible, .btn-primary:focus-visible {
