    function renderCourses(category) {
      const panel = document.getElementById('courses-panel');
      const filtered = allCourses.filter(c => c.categories.includes(category));
      const show = filtered.length > 0 ? filtered : allCourses.slice(0, 8);

      panel.style.opacity = '0';
      panel.style.transform = 'translateY(8px)';

      setTimeout(() => {
        panel.innerHTML = show.map(c => `
          <article class="course-card" tabindex="0" role="article" aria-label="Course: ${c.title}">
            <div class="course-thumb">
              <div class="course-thumb-placeholder ${c.color}"></div>
              ${c.badge ? `<span class="course-badge">${c.badge}</span>` : ''}
            </div>
            <div class="course-body">
              <h3 class="course-title">${c.title}</h3>
              <p class="course-instructor">${c.instructor}</p>
              <div class="course-meta">
                <span class="course-students">
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                    <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/>
