                  </svg>
                  ${c.students}
                </span>
                <span class="course-duration">${c.duration}</span>
              </div>
            </div>
          </article>
        `).join('');

        panel.style.transition = 'opacity 220ms ease, transform 220ms ease';
        panel.style.opacity = '1';
        panel.style.transform = 'translateY(0)';
      }, 120);
    }

    function switchTab(btn) {
      document.querySelectorAll('.tab-btn').forEach(b => {
        b.classList.remove('active');
        b.setAttribute('aria-selected', 'false');
      });
      btn.classList.add('active');
      btn.setAttribute('aria-selected', 'true');
      renderCourses(btn.dataset.category);
    }

    function filterCourses(cat) {
      document.querySelectorAll('.tab-btn').forEach(b => {
        const match = b.dataset.category === cat;
        b.classList.toggle('active', match);
        b.setAttribute('aria-selected', String(match));
      });
      document.getElementById('courses').scrollIntoView({ behavior: 'smooth', block: 'start' });
      renderCourses(cat);
    }

    // ── FAQ Accordion ───────────────────────────────────────
    function toggleFaq(btn) {
      const item = btn.closest('.faq-item');
      const isOpen = item.classList.contains('open');

      // Close all
      document.querySelectorAll('.faq-item').forEach(el => {
        el.classList.remove('open');
        el.querySelector('.faq-question').setAttribute('aria-expanded', 'false');
      });

      // Open clicked if it was closed
      if (!isOpen) {
        item.classList.add('open');
        btn.setAttribute('aria-expanded', 'true');
      }
    }

    // ── Teacher Carousel ────────────────────────────────────
    function scrollCarousel(dir) {
      const carousel = document.getElementById('teacherCarousel');
      const cardWidth = 240; // card width + gap
      carousel.scrollBy({ left: dir * cardWidth * 2, behavior: 'smooth' });
    }

